'use strict';
const tasks=window.TASKS,items=window.ITEMS||{},key='gmscw-mage-progress-v1';
const validIds=new Set(tasks.map(t=>t.id));let completed=new Set(),hideCompleted=false,category='全部';
try{const saved=JSON.parse(localStorage.getItem(key)||'{}');completed=new Set((Array.isArray(saved.completed)?saved.completed:[]).filter(id=>validIds.has(id)));hideCompleted=saved.hideCompleted===true;}catch{storageWarning();}
const $=id=>document.getElementById(id);
function storageWarning(){const e=$('storage-warning');e.hidden=false;e.textContent='浏览器未允许保存进度，当前操作仅在本次打开期间有效。';}
function save(){try{localStorage.setItem(key,JSON.stringify({completed:[...completed],hideCompleted}));}catch{storageWarning();}}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function describe(map){return Object.entries(map).map(([name,n])=>`${name} ×${n}`).join('、');}
function changeTask(id,done){if(!validIds.has(id)||typeof done!=='boolean')throw new Error('无效的任务或完成状态');if(done)completed.add(id);else completed.delete(id);save();render();}
const nodes=new Map(),phaseNodes=[];
for(const phase of [...new Set(tasks.map(t=>t.phase))]){
 const group=tasks.filter(t=>t.phase===phase);const heading=el('div','phase-heading',phase);heading.setAttribute('role','row');const count=el('span');heading.append(count);$('task-list').append(heading);phaseNodes.push({group,count});
 for(const t of group){const wrap=el('div','task-wrap');const clip=el('div','task-clip');const row=el('div','task-row');row.setAttribute('role','row');const checkCell=el('div','task-check');checkCell.setAttribute('role','cell');const check=el('input');check.type='checkbox';check.setAttribute('aria-label',`完成 ${t.title}`);check.addEventListener('change',()=>changeTask(t.id,check.checked));checkCell.append(check);const level=el('div','task-level',`Lv. ${t.level}`);level.setAttribute('role','cell');const body=el('div');body.setAttribute('role','cell');const title=el('div','task-title');title.append(el('span','task-number',t.id.slice(1)),document.createTextNode(t.title));body.append(title,el('p','task-place',t.place),el('div','task-goal',t.goal));
 if(Object.keys(t.gain).length)body.append(el('div','task-materials','获得 / 收齐：'+describe(t.gain)));
 if(Object.keys(t.cost).length)body.append(el('div','task-materials minus','消耗：'+describe(t.cost)));
 if(t.note)body.append(el('p','task-note',t.note));row.append(checkCell,level,body);clip.append(row);wrap.append(clip);$('task-list').append(wrap);nodes.set(t.id,{wrap,check});}
}
function chips(target,label,values,kind){const e=$(target);e.replaceChildren();e.className='materials '+kind;if(!values||!Object.keys(values).length)return;e.append(el('span','material-label',label));for(const [name,n] of Object.entries(values))e.append(el('span','chip',`${name} ×${n}`));}
function renderInventory(s){const all=Object.entries(s.projected).filter(([,n])=>n>0);const visible=all.filter(([name])=>category==='全部'||(items[name]?.category||'装备')===category);const grid=$('inventory-grid');grid.replaceChildren();for(const [name,n] of visible){const item=items[name];const cell=el('button','slot has-item');cell.title=`${name} ×${n}${item?.english?' · '+item.english:''}`;cell.setAttribute('aria-label',cell.title);if(item){const img=el('img');img.src=item.path;img.alt=name;img.width=32;img.height=32;img.addEventListener('error',()=>{img.remove();cell.prepend(el('span','unknown',name));},{once:true});cell.append(img);}else cell.append(el('span','unknown',name));cell.append(el('span','quantity',String(n)));const detail=()=>{$('inventory-detail').textContent=`${name} ×${n}${item?.note?' · '+item.note:''}`;};cell.addEventListener('click',detail);cell.addEventListener('mouseenter',detail);cell.addEventListener('focus',detail);grid.append(cell);}const slots=Math.max(20,Math.ceil(visible.length/5)*5);for(let n=visible.length;n<slots;n++)grid.append(el('div','slot'));$('inventory-count').textContent=`${all.length} 种道具${category==='全部'?'':` · 本栏 ${visible.length}`}`;$('inventory-detail').textContent=all.length?'选择道具查看详情':'当前没有需要保留的材料';$('deficit').textContent=s.deficits.length?'材料缺口（检查是否跳过收集）：'+s.deficits.map(([k,n])=>`${k} ${-n}`).join('、'):'';}
function render(){const s=MageLedger.snapshot(tasks,completed);$('progress-label').textContent=`${s.count} / ${tasks.length} 已完成`;$('progress').style.width=`${s.count/tasks.length*100}%`;$('step-badge').textContent=s.current?`${s.current.id.slice(1)} / ${tasks.length}`:'COMPLETE';$('current-phase').textContent=s.current?.phase||'冒险仍在继续';$('current-title').textContent=s.current?.title||'这段旅程，完成了。';$('current-place').textContent=s.current?.place||'1–32 级法师路线已全部勾选';$('current-goal').textContent=s.current?.goal||'你的任务记录和剩余材料已保存在当前浏览器。可以取消下方勾选，回看任一步。';$('current-note').textContent=s.current?.note||'';chips('current-cost','需要消耗',s.current?.cost,'cost');chips('current-gain','获得 / 收齐',s.current?.gain,'gain');$('complete-current').disabled=!s.current;$('forecast-level').textContent=s.level;const projectedDone=new Set(completed);if(s.current)projectedDone.add(s.current.id);$('forecast-job').textContent=projectedDone.has('q079')?'二转法师':projectedDone.has('q025')?'魔法师':'初心者';$('hide-completed').setAttribute('aria-checked',String(hideCompleted));for(const t of tasks){const {wrap,check}=nodes.get(t.id),done=completed.has(t.id),fold=done&&hideCompleted;check.checked=done;wrap.classList.toggle('completed',done);wrap.classList.toggle('next',t===s.current);wrap.classList.toggle('folded',fold);wrap.inert=fold;wrap.setAttribute('aria-hidden',String(fold));}for(const {group,count}of phaseNodes)count.textContent=`${group.filter(t=>completed.has(t.id)).length} / ${group.length}`;$('all-hidden').hidden=!(hideCompleted&&s.count===tasks.length);renderInventory(s);}
$('complete-current').addEventListener('click',()=>{const s=MageLedger.snapshot(tasks,completed);if(s.current)changeTask(s.current.id,true);});$('hide-completed').addEventListener('click',()=>{hideCompleted=!hideCompleted;save();render();});document.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});render();}));
render();
if(document.modelContext?.registerTool){const abort=new AbortController();addEventListener('pagehide',()=>abort.abort(),{once:true});const specs=[{name:'read_mage_progress',description:'读取法师路线当前任务、已完成步骤及预计背包。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return MageLedger.snapshot(tasks,completed);}},{name:'set_mage_task_completed',description:'设置单个任务已完成或未完成，并立即更新页面与本机保存的材料账本。',inputSchema:{type:'object',properties:{taskId:{type:'string'},completed:{type:'boolean'}},required:['taskId','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.taskId!=='string'||typeof input.completed!=='boolean')throw new Error('需要有效的 taskId 与布尔 completed');changeTask(input.taskId,input.completed);return {taskId:input.taskId,completed:input.completed,nextTask:MageLedger.snapshot(tasks,completed).current?.id||null};}}];for(const spec of specs){try{Promise.resolve(document.modelContext.registerTool(spec,{signal:abort.signal})).catch(()=>{});}catch{}}}
